package com.nextaicommerce.platform.receiving;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpSession;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import java.math.BigDecimal;import java.util.UUID;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
class InventoryLocationCorrectionTest{
 @Test void correctionUsesSelectedTenantAndConfirmsOnlyAfterTransactionReturns(){var repo=mock(InventoryRepository.class);var controller=new InventoryController(repo,null,null,null,null,null,null);var session=new MockHttpSession();UUID tenant=UUID.randomUUID(),item=UUID.randomUUID(),source=UUID.randomUUID(),destination=UUID.randomUUID();session.setAttribute("selectedTenantId",tenant);var result=controller.correctLocation(new UsernamePasswordAuthenticationToken("owner","unused"),session,item,source,destination,null,BigDecimal.TEN);assertThat(result.getStatusCode().value()).isEqualTo(200);verify(repo).correctInventoryLocation(tenant,"owner",item,source,destination,null,BigDecimal.TEN);}
 @Test void refusedCorrectionReturnsInlineError(){var repo=mock(InventoryRepository.class);doThrow(new IllegalArgumentException("Reserved stock")).when(repo).correctInventoryLocation(any(),any(),any(),any(),any(),any(),any());var controller=new InventoryController(repo,null,null,null,null,null,null);var session=new MockHttpSession();session.setAttribute("selectedTenantId",UUID.randomUUID());var result=controller.correctLocation(new UsernamePasswordAuthenticationToken("owner","unused"),session,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,BigDecimal.ONE);assertThat(result.getStatusCode().value()).isEqualTo(400);assertThat(result.getBody().message()).isEqualTo("Reserved stock");}
}
